#!/usr/bin/env bash
set -euo pipefail

ROOT="/workspaces/advocate-mahbub-website"
cd "$ROOT"

TARGET="src/scripts/hissa-calculator.js"
STAMP="$(date +%Y-%m-%d-%H%M%S)"
BACKUP_DIR="backups/hissa-sprint-3ab-$STAMP"

mkdir -p "$BACKUP_DIR"
cp "$TARGET" "$BACKUP_DIR/hissa-calculator.js"

echo "Backup created: $BACKUP_DIR"

export HissaRendererPayload=""

python3 - <<'PY'
from pathlib import Path
import base64
import os
import re

p = Path("src/scripts/hissa-calculator.js")
s = p.read_text(encoding="utf-8")

required = [
    'from "../domain/hissa/index.js"',
    '".hissa-mode-button"',
    '"#hissa-total-land"',
    '"#hissa-rows"',
    '"#hissa-result-rows"',
]
for token in required:
    if token not in s:
        raise SystemExit(f"ABORT: expected Hissa UI marker not found: {token}")

start = s.find("function renderResult(result) {")
if start < 0:
    raise SystemExit("ABORT: renderResult() was not found.")

m = re.search(r'\nfunction\s+[A-Za-z0-9_]+\s*\(', s[start + 10:])
if not m:
    raise SystemExit("ABORT: could not find the end of renderResult().")

end = start + 10 + m.start()
renderer = base64.b64decode(os.environ["HissaRendererPayload"]).decode("utf-8")
s = s[:start] + renderer + s[end:]

pattern = re.compile(
    r'const result\s*=\s*\n\s*state\.activeMode === "normal"\s*\n'
    r'\s*\?\s*calculateNormal\(payload\)\s*\n'
    r'\s*:\s*calculateGroupLine\(payload\);'
)

replacement = """const validatedRows = validateCurrentRows(payload.rows);

    const validatedPayload = {
      ...payload,
      rows: validatedRows,
    };

    const result =
      state.activeMode === "normal"
        ? calculateNormal(validatedPayload)
        : calculateGroupLine(validatedPayload);"""

if not pattern.search(s):
    raise SystemExit("ABORT: calculation selection block not found.")

s = pattern.sub(replacement, s, count=1)

p.write_text(s, encoding="utf-8")
print("Updated:", p)
PY

echo
echo "Running Hissa tests..."
node --test tests/hissa/*.test.js

echo
echo "Running production build..."
npm run build

echo
echo "SUCCESS"
echo "Backup: $BACKUP_DIR"
echo "Changed: $TARGET"
echo
echo "Browser QA:"
echo "  1. blank total land"
echo "  2. Anna=16"
echo "  3. Kora=7"
echo "  4. Bangla digits such as ১৫"
echo "  5. valid shareholder calculation"
